    /// bytes, `+0x40` set; docs/formats/menu.md "Windows"): each
    /// screen's lists and cursors.
    /// </summary>
    public List<MenuWindow> Windows = new();
    /// <summary>
    /// The character the PS2 menus show (`TkMenuGetCurrentPlayer`:
    /// `g_TkMenuPlayers` `0x01841c14` at `g_TkMenuCurrentPlayerPos`
    /// `0x01841c28`; below 8 a party member, 8 and up an aeon); 0xff
    /// when the position is 8 or more (the list is 8 bytes).
    /// </summary>
    public byte CurrentPlayer;
    /// <summary>
    /// The config menu (menu slot 10, `main_mask` bit `0x400`).
    /// </summary>
    public ConfigMenu Config = new();
    /// <summary>
    /// The battle results screen (menu slot 0x11, `main_mask` bit
    /// `0x20000`).
    /// </summary>
    public BattleEnd BattleEnd = new();
    /// <summary>
    /// The battle command window's target selection and hand cursors.
    /// </summary>
    public BattleTarget BattleTarget = new();

    /// <summary>Reads one from the encoding.</summary>
    public static Menus Read(ref StateReader r) => Read(ref r, null);

    /// <summary>
    /// Reads one into <paramref name="into"/> (a new one when null): its objects, lists,
    /// arrays and unchanged strings are reused, so a decode allocates next to nothing.
    /// </summary>
    public static Menus Read(ref StateReader r, Menus? into)
    {
        var o = into ?? new Menus();
        o.MainMask = r.U32();
        o.MainCursor = r.I32();
        o.MainOptions = r.I32();
        {
            int n = r.U16();
            var l = o.MainOptionList;
            for (int i = 0; i < n; i++)
            {
                if (i < l.Count)
                    l[i] = MenuOption.Read(ref r, l[i]);
                else
                    l.Add(MenuOption.Read(ref r, null));
            }
            if (l.Count > n)
                l.RemoveRange(n, l.Count - n);
        }
        o.BattleWindow = r.U32();
        o.BattleCharacter = r.I16();
        o.BattleDepth = r.I16();
        o.BattleCursor = r.I16();
        o.BattleIds = r.Bytes(o.BattleIds);
        o.SaveState = r.U32();
        o.SaveCursor = r.I32();
        o.SaveTop = r.I32();
        o.SaveRows = r.I32();
        o.SaveFiles = r.I32();
        o.EscMenu = r.Bool();
        {
            int n = r.U16();
            var l = o.Windows;
            for (int i = 0; i < n; i++)
            {
                if (i < l.Count)
                    l[i] = MenuWindow.Read(ref r, l[i]);
                else
                    l.Add(MenuWindow.Read(ref r, null));
            }
            if (l.Count > n)
                l.RemoveRange(n, l.Count - n);
        }
        o.CurrentPlayer = r.U8();
        o.Config = ConfigMenu.Read(ref r, o.Config);
        o.BattleEnd = BattleEnd.Read(ref r, o.BattleEnd);
        o.BattleTarget = BattleTarget.Read(ref r, o.BattleTarget);
        return o;
    }
}

