    /// curve 1, limit 1.
    /// </summary>
    public float FogNear;
    public float FogFar;
    public float FogCurve;
    public float FogLimit;
    /// <summary>
    /// `CharacterAmbientLight` (the scene context `+0xac`, reached as
    /// the lighting's `+0x18c`: the ambient colour times its level).
    /// </summary>
    public Vector3 CharacterAmbient;
    /// <summary>
    /// The character lights 0-2 (`PhyreChrLitShader`'s `Light0`..
    /// `Light2`), empty before the lighting is initialised.
    /// </summary>
    public List<Light> Lights = new();
    /// <summary>
    /// The shaders' `GlobalTime`, seconds (context `+0xd0`, that is
    /// `*g_PhyreApplication +0x120`: `FFXApplication +0x3b0`'s copy):
    /// the clock of scrolling UVs (`phyreuvanimationshader`'s
    /// `ScrollSpeed x GlobalTime`) and the water; it advances while the
    /// game runs (not loading, not paused), wraps to 0 at 2400 and is 0
    /// again after every map change (docs/harness.md, the section on
    /// `GlobalTime` and the title band).
    /// </summary>
    public float GlobalTime;

    /// <summary>Reads one from the encoding.</summary>
    public static Look Read(ref StateReader r) => Read(ref r, null);

    /// <summary>
    /// Reads one into <paramref name="into"/> (a new one when null): its objects, lists,
    /// arrays and unchanged strings are reused, so a decode allocates next to nothing.
    /// </summary>
    public static Look Read(ref StateReader r, Look? into)
    {
        var o = into ?? new Look();
        o.Valid = r.Bool();
        o.ColourScale = r.Vec3();
        o.Ambient = r.Vec3();
        o.Background = r.Vec3();
        o.GlowFull = r.F32();
        o.GlowNone = r.F32();
        o.GlowGain = r.F32();
        o.GlowSpread = r.F32();
        o.FogColour = r.Vec3();
        o.FogNear = r.F32();
        o.FogFar = r.F32();
        o.FogCurve = r.F32();
        o.FogLimit = r.F32();
        o.CharacterAmbient = r.Vec3();
        {
            int n = r.U16();
            var l = o.Lights;
            for (int i = 0; i < n; i++)
            {
                if (i < l.Count)
                    l[i] = Light.Read(ref r, l[i]);
                else
                    l.Add(Light.Read(ref r, null));
            }
            if (l.Count > n)
                l.RemoveRange(n, l.Count - n);
        }
        o.GlobalTime = r.F32();
        return o;
    }
}

