{
    /// <summary>
    /// Its slot (0..31): `{VAR:n}` is code `0x12`, `0x30 + n`.
    /// </summary>
    public byte Slot;
    /// <summary>
    /// Its kind as the text reads it (`+1`; `TOResetMessageVars`
    /// copies the script's `+0` there): 0 a text at `value`, 1 a
    /// number, 2 a number with digit groups, `0x13`..`0x23` a macro
    /// code (`value / 0xd0` added to the code, `value % 0xd0` its
    /// argument), `0x2b`..`0x32` a number of `kind - 0x2a` digits, `0x33`
    /// an item's name, `0x34` a weapon's, `0x35` a command's, `0x36` an
    /// ability's, `0x37` the field pickup (`value` a treasure, `takara`).
    /// </summary>
    public byte Kind;
    /// <summary>
    /// Its value (`i32 +4`).
    /// </summary>
    public int Value;
    /// <summary>
    /// What `{VAR:n}` expands to, in the game's encoding (empty when
    /// it expands to nothing).
    /// </summary>
    public byte[] Text = [];
    /// <summary>
    /// For `0x37`: the treasure's kind (`takara` record `+0`: 2 an
    /// item, 5 gear, 10 a key item, others gil; `msFieldItemGet`), else
    /// 0xff.
    /// </summary>
    public byte Pickup;
    /// <summary>
    /// For `0x37`: the item or key item id (record `u16 +2`), or the
    /// gear's id in the pickup's spoils (`0x02310dce`, a `0xb000` id).
    /// </summary>
    public ushort PickupId;
    /// <summary>
    /// For `0x37`: the items' count (record `+1`), or the gil (`+1` x
    /// 100).
    /// </summary>
    public uint PickupCount;

    /// <summary>Reads one from the encoding.</summary>
    public static MessageVar Read(ref StateReader r) => Read(ref r, null);

    /// <summary>
    /// Reads one into <paramref name="into"/> (a new one when null): its objects, lists,
    /// arrays and unchanged strings are reused, so a decode allocates next to nothing.
    /// </summary>
    public static MessageVar Read(ref StateReader r, MessageVar? into)
    {
        var o = into ?? new MessageVar();
        o.Slot = r.U8();
        o.Kind = r.U8();
        o.Value = r.I32();
        o.Text = r.Bytes(o.Text);
        o.Pickup = r.U8();
        o.PickupId = r.U16();
        o.PickupCount = r.U32();
        return o;
    }
}

/// <summary>
/// A damage number as the battle shows it: the characters
/// `MsNumberRegist` (`0x0079fa00`) put for one number, rebuilt from the
/// list of `g_BtlNumbers`' records (0x14 bytes each: `+0` style, `+1`
/// colour, `+2` the battler, `+3` the place, `+4` the character, `+5`
/// the delay, `+6` the age, `+7` the life). `MsSubHP` registers the HP
/// loss before it clamps the HP at 0: a killing blow shows its
/// overkill.
/// </summary>
public sealed partial class BattleNumber
{
    /// <summary>
    /// The battler it stands over (`+2`; 0..0x11 the party,
    /// 0x14..0x1b the monsters).
    /// </summary>
    public byte Battler;
    /// <summary>
    /// The digits' value (at most 9 digits); -1 for a word alone. A CTB
    /// number (kind 2, `MsSubCTB`) looks the same as an HP one (kind 0):
    /// digits and no word.
    /// </summary>
    public int Value;
    /// <summary>
    /// How many digits (0 for a word alone).
    /// </summary>
    public byte Digits;
    /// <summary>
    /// Its colour (`+1`): 0 a loss (grey, bouncing), 1 a heal (green,
    /// rising by half its age: the value negative, or 0 with the other
    /// part negative), 2 the overkill word (grey, rising by its age);
    /// a heal's `value` is the amount healed.
    /// </summary>
    public byte Colour;
    /// <summary>
    /// The word after the digits, a glyph of the damage font (0 none):
    /// 0x3a "MP" (kind 1, `MsSubMP`), 0x3b and 0x3c the words of kinds
    /// 3 and 4 (an action's result `+1`, `AfterDamageProcess`), 0x3d
    /// the overkill's (kind 5, `MsDamageCheckDeath`).
    /// </summary>
    public byte Word;
    /// <summary>
    /// The style (`+0`): bit 7 at the battler's second number point;
    /// `&amp; 0x7f` 1 or 2 the numbers the battle waits on
    /// (`g_BtlNumbersKind1`, `g_BtlNumbersKind12`).
    /// </summary>
    public byte Style;
    /// <summary>
    /// Updates since it was put (`+6`, `MsNumberCalcProcess` adds 1 an
    /// update): a new number reads 0 or 1 in the snapshot after its
    /// update, by who put it (effect and motion damage after the step:
    /// 0; the status step's Regen/Zombie numbers and `chr_damage`'s HP
    /// loss before it: 1). Spot new numbers by comparing snapshots, not
    /// by `age == 0`.
    /// </summary>
    public byte Age;
    /// <summary>
    /// The age past which it is removed (`+7`, 30); its characters
    /// fade over their last 5 frames.
    /// </summary>
    public byte Life;
    /// <summary>
    /// Updates until all its characters show (the most `+5` left):
    /// the character in place `k` waits `k + 1` updates from its put
    /// (it shows from age `k + 1`), the lowest digit first; 0 when the
    /// whole number shows.
    /// </summary>
    public byte Delay;
    /// <summary>
    /// The battler's number point on the PS2 screen (512 x 416), where
    /// `MsNumberDrawProcess` centres it (`+0xf44`, `+0xf48`; `+0xf4c`,
    /// `+0xf50` with style bit 7).
    /// </summary>
    public int X;
    /// <summary>
    /// See `x`.
    /// </summary>
    public int Y;

    /// <summary>Reads one from the encoding.</summary>
    public static BattleNumber Read(ref StateReader r) => Read(ref r, null);

    /// <summary>
    /// Reads one into <paramref name="into"/> (a new one when null): its objects, lists,
    /// arrays and unchanged strings are reused, so a decode allocates next to nothing.
    /// </summary>
    public static BattleNumber Read(ref StateReader r, BattleNumber? into)
    {
        var o = into ?? new BattleNumber();
        o.Battler = r.U8();
        o.Value = r.I32();
        o.Digits = r.U8();
        o.Colour = r.U8();
        o.Word = r.U8();
        o.Style = r.U8();
        o.Age = r.U8();
        o.Life = r.U8();
        o.Delay = r.U8();
        o.X = r.I32();
        o.Y = r.I32();
        return o;
    }
}
